int set_task_attr(struct task_struct *task, char *name, void *value, size_t size)
{
    if (size == 0)
        return -EINVAL;

    if (current->pid != task->pid)
        return -EPERM;

    if (!value) {
        printk(KERN_ERR "Failed to set attribute: value is NULL\n");
        return -EFAULT;
    }

    char *str_value = kmalloc(size + 1, GFP_KERNEL);
    if (!str_value)
        return -ENOMEM;

    memcpy(str_value, value, size);
    str_value[size] = '\0';

    if (strncmp(name, "apparmor", 8) == 0) {
        char *command = strsep(&str_value, " ");
        if (!command) {
            kfree(str_value);
            return -EINVAL;
        }

        if (strncmp(command, "profile", 7) == 0) {
            char *profile_name = strsep(&str_value, " ");
            if (!profile_name) {
                kfree(str_value);
                return -EINVAL;
            }

            int ret = set_apparmor_profile(task, profile_name);
            if (ret < 0) {
                audit_log(current->audit_context, AUDIT_APPARMOR, "Failed to set profile", 0);
                kfree(str_value);
                return ret;
            }
        } else {
            kfree(str_value);
            return -EINVAL;
        }
    } else {
        kfree(str_value);
        return -EINVAL;
    }

    kfree(str_value);
    return size;
}

int set_apparmor_process_attr(struct task_struct *task, char *name, void *value, size_t size) {
    if (size == 0) {
        return -EINVAL;
    }

    if (current != task) {
        return -EPERM;
    }

    char *str_val = (char *)value;
    if (str_val[size - 1] != '\0') {
        return -EINVAL;
    }

    char *command = strsep(&str_val, ":");

    if (!strcmp(name, "profile")) {
        if (!strcmp(command, "enforce")) {
            return aa_enforce_profile(task, str_val);
        } else if (!strcmp(command, "complain")) {
            return aa_complain_profile(task, str_val);
        } else {
            audit_log(KERN_WARNING "AppArmor: Unknown command for profile attribute: %s", command);
            return -EINVAL;
        }
    } else if (!strcmp(name, "namespace")) {
        if (!strcmp(command, "change")) {
            return aa_change_namespace(task, str_val);
        } else {
            audit_log(KERN_WARNING "AppArmor: Unknown command for namespace attribute: %s", command);
            return -EINVAL;
        }
    } else {
        audit_log(KERN_WARNING "AppArmor: Unknown attribute: %s", name);
        return -EINVAL;
    }

    return size;
}

#include <linux/sched.h>
#include <linux/cred.h>
#include <linux/audit.h>

int set_apparmor_process_attr(struct task_struct *task, char *name, void *value, size_t size)
{
    if (size == 0)
        return -EINVAL;

    if (current->pid != task->pid)
        return -EPERM;

    char *str_value = value;
    if (!str_value[size - 1])
        return -EINVAL;

    char *command = str_value;
    if (!command)
        return -EINVAL;

    int ret = 0;
    if (strcmp(name, "profile") == 0) {
        if (strcmp(command, "change") == 0) {
            ret = change_process_profile(task, str_value);
        } else {
            ret = -EINVAL;
        }
    } else {
        ret = -EINVAL;
    }

    if (ret < 0) {
        audit_log(current->audit_context, AUDIT_APPARMOR, "set_process_attr failed", "error", ret);
    }

    return ret ? ret : (int)size;
}

int set_aa_process_attr(struct task_struct *task, char *name, void *value, size_t size) {
    if (size == 0 || task != current) {
        return -EINVAL;
    }

    if (!value || !*((char *)value)) {
        return -EINVAL;
    }

    char *command = value;
    if (strcmp(name, "security") == 0) {
        if (strcmp(command, "change_hat") == 0) {
            int ret = aa_change_hat(task, command);
            if (ret < 0) {
                audit_log(current->audit_context, AUDIT_AA_CHANGE_HAT, "failed to change_hat: %d", ret);
                return ret;
            }
        } else if (strcmp(command, "set_hat") == 0) {
            int ret = aa_set_hat(task, command);
            if (ret < 0) {
                audit_log(current->audit_context, AUDIT_AA_SET_HAT, "failed to set_hat: %d", ret);
                return ret;
            }
        } else {
            return -ENOPARAM;
        }
    } else {
        return -ENOPARAM;
    }

    return (int)size;
}

int aa_setprocattr(struct task_struct *task, char *name, void *value, size_t size)
{
    if (size == 0)
        return -EINVAL;

    if (current != task)
        return -EPERM;

    if (!value || !((char *)value)[0])
        return -EINVAL;

    char command[AA_COMMAND_SIZE];
    if (snprintf(command, sizeof(command), "%s", value) < 0)
        return -EFAULT;

    if (strcmp(name, "change_hat") == 0) {
        int ret = aa_change_hat(task, command);
        if (ret < 0) {
            audit_log(current->audit_context, GFP_KERNEL, AUDIT_APPARMOR,
                      "aa_setprocattr failed to change_hat", 0, "error", ret, 0);
            return ret;
        }
    } else {
        audit_log(current->audit_context, GFP_KERNEL, AUDIT_APPARMOR,
                  "aa_setprocattr unknown attribute", 0, "name", name, 0);
        return -EINVAL;
    }

    return size;
}
